package com.finny.pet.data.database

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import kotlinx.coroutines.flow.Flow

@Dao interface ProfileDao { @Query("SELECT * FROM profiles WHERE id=1") fun observe(): Flow<ProfileEntity?>; @Query("SELECT * FROM profiles WHERE id=1") suspend fun get():ProfileEntity?; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(value: ProfileEntity); @Query("DELETE FROM profiles") suspend fun clear() }
@Dao interface PetDao { @Query("SELECT * FROM pets WHERE profileId=1") fun observe(): Flow<PetEntity?>; @Query("SELECT * FROM pets WHERE profileId=1") suspend fun get():PetEntity?; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(value: PetEntity); @Query("DELETE FROM pets") suspend fun clear() }
@Dao interface BalanceDao { @Query("SELECT * FROM balances WHERE profileId=1") fun observe(): Flow<BalanceEntity?>; @Query("SELECT * FROM balances WHERE profileId=1") suspend fun get(): BalanceEntity?; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(value: BalanceEntity); @Query("DELETE FROM balances") suspend fun clear() }
@Dao interface PeriodDao { @Query("SELECT * FROM periods ORDER BY number") fun observeAll(): Flow<List<PeriodEntity>>; @Query("SELECT * FROM periods WHERE number=:number") suspend fun get(number: Int): PeriodEntity?; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(value: PeriodEntity); @Query("DELETE FROM periods") suspend fun clear() }
@Dao interface GoalDao { @Query("SELECT * FROM goals ORDER BY cost") fun observeAll(): Flow<List<GoalEntity>>; @Query("SELECT * FROM goals WHERE id=:id") suspend fun get(id: String): GoalEntity?; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(value: GoalEntity); @Query("DELETE FROM goals") suspend fun clear() }
@Dao interface PurchaseDao { @Query("SELECT * FROM purchases ORDER BY id DESC") fun observeAll(): Flow<List<PurchaseEntity>>; @Insert suspend fun insert(value: PurchaseEntity); @Query("DELETE FROM purchases") suspend fun clear() }
@Dao interface LessonDao { @Query("SELECT * FROM lessons") fun observeAll(): Flow<List<LessonEntity>>; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(value: LessonEntity); @Query("DELETE FROM lessons") suspend fun clear() }
@Dao interface ProgressDao { @Query("SELECT * FROM progress") fun observeAll(): Flow<List<ProgressEntity>>; @Query("SELECT * FROM progress WHERE `key`=:key") suspend fun get(key: String): ProgressEntity?; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(value: ProgressEntity); @Query("DELETE FROM progress") suspend fun clear() }
@Dao interface InventoryDao { @Query("SELECT * FROM inventory ORDER BY category,title") fun observeAll():Flow<List<InventoryEntity>>; @Query("SELECT * FROM inventory WHERE itemId=:id") suspend fun get(id:String):InventoryEntity?; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(value:InventoryEntity); @Query("DELETE FROM inventory") suspend fun clear() }
@Dao interface SkinDao { @Query("SELECT * FROM skin_ownership ORDER BY title") fun observeAll():Flow<List<SkinOwnershipEntity>>; @Query("SELECT * FROM skin_ownership WHERE skinId=:id") suspend fun get(id:String):SkinOwnershipEntity?; @Query("SELECT * FROM skin_ownership WHERE equipped=1 LIMIT 1") suspend fun getEquipped():SkinOwnershipEntity?; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(value:SkinOwnershipEntity); @Query("UPDATE skin_ownership SET equipped=0") suspend fun unequipAll(); @Query("DELETE FROM skin_ownership") suspend fun clear() }
@Dao interface PetNeedsDao { @Query("SELECT * FROM pet_needs WHERE profileId=1") fun observe():Flow<PetNeedsEntity?>; @Query("SELECT * FROM pet_needs WHERE profileId=1") suspend fun get():PetNeedsEntity?; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(value:PetNeedsEntity); @Query("DELETE FROM pet_needs") suspend fun clear() }
@Dao interface TaskProgressV2Dao { @Query("SELECT * FROM task_progress_v2") fun observeAll():Flow<List<TaskProgressV2Entity>>; @Query("SELECT * FROM task_progress_v2 WHERE taskId=:id") suspend fun get(id:String):TaskProgressV2Entity?; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(value:TaskProgressV2Entity); @Query("DELETE FROM task_progress_v2") suspend fun clear() }
@Dao interface WalletTransactionDao { @Query("SELECT * FROM wallet_transactions ORDER BY id DESC") fun observeAll():Flow<List<WalletTransactionEntity>>; @Insert suspend fun insert(value:WalletTransactionEntity); @Query("DELETE FROM wallet_transactions") suspend fun clear() }
@Dao interface PetLevelDao { @Query("SELECT * FROM pet_levels WHERE profileId=1") fun observe():Flow<PetLevelEntity?>; @Query("SELECT * FROM pet_levels WHERE profileId=1") suspend fun get():PetLevelEntity?; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(value:PetLevelEntity); @Query("DELETE FROM pet_levels") suspend fun clear() }
